@push('scripts')
<script>
(() => {
 const dataNode=document.getElementById('calendar-events'); if(!dataNode)return;
 const events=JSON.parse(dataNode.textContent||'[]'); const grid=document.getElementById('calendar-grid');
 const title=document.getElementById('calendar-month-title'); const detailTitle=document.getElementById('selected-date-title'); const detail=document.getElementById('selected-events');
 const today=new Date(); today.setHours(0,0,0,0); let viewDate=new Date(today.getFullYear(),today.getMonth(),1); let selected=fmt(today);
 const months=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
 const days=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
 function fmt(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
 function pretty(s){const d=new Date(s+'T12:00:00');return days[d.getDay()]+', '+d.getDate()+' '+months[d.getMonth()]+' '+d.getFullYear()}
 function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
 function render(){title.textContent=months[viewDate.getMonth()]+' '+viewDate.getFullYear();grid.innerHTML='';let first=new Date(viewDate.getFullYear(),viewDate.getMonth(),1);let offset=(first.getDay()+6)%7;let start=new Date(first);start.setDate(first.getDate()-offset);
  for(let i=0;i<42;i++){let d=new Date(start);d.setDate(start.getDate()+i);let key=fmt(d);let list=events.filter(e=>e.date===key);let b=document.createElement('button');b.type='button';b.className='calendar-day'+(d.getMonth()!==viewDate.getMonth()?' is-outside':'')+(key===fmt(today)?' is-today':'')+(key===selected?' is-selected':'');b.setAttribute('aria-label',pretty(key)+(list.length?', '+list.length+' agenda':''));b.innerHTML='<span class="day-number">'+d.getDate()+'</span><span class="day-events">'+list.slice(0,2).map(e=>'<span class="day-event" title="'+esc(e.title)+'">'+esc(e.title)+'</span>').join('')+(list.length>2?'<span class="day-more">+'+(list.length-2)+' lagi</span>':'')+'</span>';b.addEventListener('click',()=>{selected=key;if(d.getMonth()!==viewDate.getMonth())viewDate=new Date(d.getFullYear(),d.getMonth(),1);render();renderDetail()});grid.appendChild(b)}
 }
 function renderDetail(){detailTitle.textContent=pretty(selected);let list=events.filter(e=>e.date===selected);if(!list.length){detail.innerHTML='<p class="calendar-empty">Belum ada agenda pada tanggal ini.</p>';return}detail.innerHTML=list.map(e=>'<article class="calendar-event-detail"><h3>'+esc(e.title)+'</h3><p class="event-time">'+esc(e.start)+(e.end?'–'+esc(e.end):'')+'</p><p>⌖ '+esc(e.location)+'</p>'+(e.description?'<p>'+esc(e.description)+'</p>':'')+'</article>').join('')}
 document.getElementById('calendar-prev').addEventListener('click',()=>{viewDate=new Date(viewDate.getFullYear(),viewDate.getMonth()-1,1);render()});document.getElementById('calendar-next').addEventListener('click',()=>{viewDate=new Date(viewDate.getFullYear(),viewDate.getMonth()+1,1);render()});document.getElementById('calendar-today').addEventListener('click',()=>{viewDate=new Date(today.getFullYear(),today.getMonth(),1);selected=fmt(today);render();renderDetail()});document.querySelectorAll('[data-calendar-date]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.calendarDate;let d=new Date(selected+'T12:00:00');viewDate=new Date(d.getFullYear(),d.getMonth(),1);render();renderDetail();document.querySelector('.calendar-shell').scrollIntoView({behavior:'smooth',block:'start'})}));render();renderDetail();
})();
</script>
@endpush